def gen(rng):
    def fmt(cases):
        lines = [str(len(cases))]
        for c in cases:
            lines.append(str(len(c)))
            for s, e in c:
                lines.append(f"{s} {e}")
        return '\n'.join(lines)

    def rc(n, hi):
        res = []
        for _ in range(n):
            e = rng.randint(1, hi - 1)
            s = rng.randint(e + 1, hi)
            res.append((s, e))
        return res

    tests = [
        fmt([[(4, 1), (5, 4), (7, 3)]]),
        fmt([[(2, 1)]]),
        fmt([[(2, 1), (4, 3)], [(5, 4), (9, 6)]]),
        fmt([[(10, 1), (10, 1), (10, 1)]]),
        fmt([[(i + 2, i + 1) for i in range(6)]]),
        fmt([[(10 ** 9, 1), (10 ** 9, 2), (10 ** 9 - 1, 5)]]),
    ]
    for n in (1, 2, 3, 5, 7, 9, 11):
        for hi in (4, 8, 30):
            tests.append(fmt([rc(n, hi) for _ in range(2)]))
    for _ in range(6):
        tests.append(fmt([rc(rng.randint(1, 12), rng.choice([5, 12, 40])) for _ in range(3)]))
    big = 200000
    tests.append(fmt([rc(big, 10 ** 9)]))
    tests.append(fmt([rc(big, 1000)]))
    tests.append(fmt([[(10 ** 9 - i, 1 + i) for i in range(big)]]))
    tests.append(fmt([rc(big // 10, 10 ** 9) for _ in range(10)]))
    tests.append(fmt([[(i + 2, i + 1) for i in range(big)]]))
    return tests
